@Service
public class GimbalAiService {
    private static final Logger log = ...;
    private final GimbalAiClient client;

    public GimbalAiAnswer ask(PrincipalContext principal, String text) {
        if (principal.principalType() != PrincipalType.GIMBAL) {
            throw new ApiException(ErrorCode.CALLER_NOT_ALLOWED, "only a gimbal may use the AI text passthrough");
        }
        try {
            String answerText = client.answer(text);
            return new GimbalAiAnswer(answerText);
        } catch (GimbalAiException failure) {
            ErrorCode code = switch (failure.kind()) {
                case TIMEOUT -> ErrorCode.DEPENDENCY_TIMEOUT;
                case MALFORMED, UNAVAILABLE -> ErrorCode.DEPENDENCY_UNAVAILABLE;
            };
            log.warn("gimbal AI downstream failure kind={} httpStatus={} downstreamCode={}",
                    failure.kind(), failure.httpStatus(), failure.safeCode());
            throw new ApiException(code, "gimbal AI dependency failure; no answer available");
        }
    }
}
