package cn.yuanxin.mvp.web.gimbalai.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;

/**
 * 云台 AI 文本透传请求体。
 *
 * <p><b>严格形状</b>：仅允许 {@code text} 一个字段。未知字段由全局
 * {@code spring.jackson.deserialization.fail-on-unknown-properties=true}
 * 拒绝 → 400 INVALID_INPUT（与项目既有严格请求体约定一致）。</p>
 *
 * <p>{@code text} 去空白后不得为空，长度上限 {@value #MAX_TEXT_LENGTH} 字符
 * （该上限是服务端本地策略，与下游 AI 契约的 input.text 上限无关）。</p>
 */
public record GimbalAiMessageRequest(
        @NotBlank(message = "text must not be blank")
        @Size(max = 2000, message = "text must not exceed 2000 characters")
        String text) {

    /** 服务端接受的用户文本最大长度（字符）。 */
    public static final int MAX_TEXT_LENGTH = 2000;
}

package cn.yuanxin.mvp.web.gimbalai.dto;

/**
 * 云台 AI 文本透传成功响应 {@code data}。
 *
 * <p>只保留下游 {@code answer.text} 原文；下游 {@code invocation_id}/
 * {@code request_id}/会话引用/用量等元数据绝不外发。</p>
 */
public record GimbalAiAnswer(String answerText) {
}

package cn.yuanxin.mvp.web.gimbalai;

/**
 * 云台 AI 下游失败分类：由 HTTP 客户端按"传输/响应形状"归类，供服务层映射到
 * 既有错误码。绝不携带用户文本或密钥。
 */
public enum GimbalAiFailureKind {

    /** 2xx 但响应不是合法 JSON / 缺 {@code answer.text} / 类型不符（上游契约违约）。 */
    MALFORMED,

    /** 连接/传输失败，或下游返回非 2xx（含 problem+json）。 */
    UNAVAILABLE,

    /** 连接或读取超时。 */
    TIMEOUT
}

package cn.yuanxin.mvp.web.gimbalai;

/**
 * 云台 AI 下游失败（类型化）。<b>绝不</b>承载用户文本或 API Key：{@link #getMessage()}
 * 只使用固定安全文案，HTTP 状态/下游业务码仅用于服务端日志。
 *
 * <p>任何失败都不得回退为替身或合成答案——上层见此异常必须返回依赖类问题。</p>
 */
public class GimbalAiException extends RuntimeException {

    private final GimbalAiFailureKind kind;
    private final Integer httpStatus;
    private final String safeCode;

    public GimbalAiException(GimbalAiFailureKind kind, String message) {
        this(kind, message, null, null);
    }

    public GimbalAiException(GimbalAiFailureKind kind, String message, Integer httpStatus,
                             String safeCode) {
        super(message);
        this.kind = kind;
        this.httpStatus = httpStatus;
        this.safeCode = safeCode;
    }

    public GimbalAiFailureKind kind() {
        return kind;
    }

    /** 下游 HTTP 状态；无（传输失败）时为 null。 */
    public Integer httpStatus() {
        return httpStatus;
    }

    /** 下游 problem+json 的 {@code code}（若可解析）；仅用于日志。 */
    public String safeCode() {
        return safeCode;
    }
}

