 * <p>超时默认 connect 3s / read 10s（下游为同步问答，读取上限应在部署时按需调整）。</p>
 */
@ConfigurationProperties(prefix = "app.gimbal-ai")
public record GimbalAiProperties(
        String baseUrl,
        String apiKey,
        Integer connectTimeoutMillis,
        Integer readTimeoutMillis) {

    public static final int DEFAULT_CONNECT_TIMEOUT_MILLIS = 3000;
    public static final int DEFAULT_READ_TIMEOUT_MILLIS = 10000;
    public static final int MIN_TIMEOUT_MILLIS = 1000;

    public GimbalAiProperties {
        baseUrl = trimToNull(baseUrl);
        apiKey = trimToNull(apiKey);
        connectTimeoutMillis = normalizeTimeout(connectTimeoutMillis, DEFAULT_CONNECT_TIMEOUT_MILLIS);
        readTimeoutMillis = normalizeTimeout(readTimeoutMillis, DEFAULT_READ_TIMEOUT_MILLIS);
    }

    /** 缺失的必填键（仅键名，绝不回显值）。 */
    public List<String> missingRequiredKeys() {
        List<String> missing = new ArrayList<>();
        if (baseUrl == null) {
            missing.add("app.gimbal-ai.base-url");
        }
        if (apiKey == null) {
            missing.add("app.gimbal-ai.api-key");
        }
        return missing;
    }

    /** base-url 去掉结尾斜杠，避免与下游路径拼接出双斜杠。 */
    public String normalizedBaseUrl() {
        if (baseUrl == null) {
            return null;
        }
        return baseUrl.endsWith("/") ? baseUrl.substring(0, baseUrl.length() - 1) : baseUrl;
    }

    @Override
    public String toString() {
        return "GimbalAiProperties[baseUrl=" + baseUrl
                + ", apiKey=" + (apiKey == null ? "<absent>" : "<redacted>")
                + ", connectTimeoutMillis=" + connectTimeoutMillis
                + ", readTimeoutMillis=" + readTimeoutMillis + "]";
    }

    private static Integer normalizeTimeout(Integer value, int fallback) {
        int normalized = value == null || value <= 0 ? fallback : value;
        return Math.max(MIN_TIMEOUT_MILLIS, normalized);
    }

    private static String trimToNull(String value) {
        if (value == null) {
            return null;
        }
        String trimmed = value.trim();
        return trimmed.isEmpty() ? null : trimmed;
    }
}

package cn.yuanxin.mvp.web.gimbalai;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ObjectNode;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.io.IOException;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.net.http.HttpTimeoutException;
import java.nio.charset.StandardCharsets;
import java.security.SecureRandom;
import java.time.Duration;
import java.util.UUID;

/**
 * 云台 AI 文本透传下游客户端（JDK {@link HttpClient}；无状态、无重试回退）。
 *
 * <p>固定契约（对 {@code POST {base}/internal/v1/ai/responses}）：</p>
 * <ul>
 *   <li>Header：{@code X-Service-Name=medical-platform}、{@code X-API-Key}（配置）、
 *       {@code X-Request-Id}（每次调用服务端新生成）、{@code Idempotency-Key}
 *       （<b>每次调用全新</b>，故客户端重试会产生<b>新问题</b>；本增量无本地幂等存储）、
 *       {@code X-Protocol-Version=1.0}、{@code traceparent}（W3C）、
 *       {@code Accept}/{@code Content-Type: application/json}；</li>
 *   <li>Body：{@code {"protocol_version":"1.0","request_id":"<X-Request-Id>",
 *       "use_case":"APP_AGENT_CONVERSATION","input":{"text":"<用户文本>"}}}；
 *       <b>不含</b> {@code continuation_state}（无上下文）；</li>
 *   <li>2xx：严格取 {@code answer.text}（非 JSON / 缺字段 / 类型不符 → {@code MALFORMED}）；
 *       非 2xx / 传输失败 → {@code UNAVAILABLE}；超时 → {@code TIMEOUT}。</li>
 * </ul>
 *
 * <p><b>日志</b>：只记下游 requestId / HTTP 状态 / 下游错误码；绝不记 API Key、
 * 用户文本（连长度也不记）。<b>绝不</b>把失败当成功、绝不回退替身。</p>
 */
public class HttpGimbalAiClient implements GimbalAiClient {

    private static final Logger log = LoggerFactory.getLogger(HttpGimbalAiClient.class);

    static final String SERVICE_NAME = "medical-platform";
    static final String USE_CASE = "APP_AGENT_CONVERSATION";
    static final String PROTOCOL_VERSION = "1.0";
    static final String RESPONSES_PATH = "/internal/v1/ai/responses";

    private static final SecureRandom RANDOM = new SecureRandom();

    private final HttpClient httpClient;
    private final ObjectMapper objectMapper;
    private final URI endpoint;
    private final String apiKey;
    private final Duration readTimeout;

    public HttpGimbalAiClient(GimbalAiProperties properties, ObjectMapper objectMapper) {
        this(properties, objectMapper, HttpClient.newBuilder()
                .connectTimeout(Duration.ofMillis(properties.connectTimeoutMillis()))
                .build());
    }

    /** 测试用构造器：注入自定义 HttpClient（如指向本地 stub 的连接池）。 */
    HttpGimbalAiClient(GimbalAiProperties properties, ObjectMapper objectMapper,
                       HttpClient httpClient) {
        this.objectMapper = objectMapper;
        this.httpClient = httpClient;
        this.endpoint = URI.create(properties.normalizedBaseUrl() + RESPONSES_PATH);
        this.apiKey = properties.apiKey();
        this.readTimeout = Duration.ofMillis(properties.readTimeoutMillis());
    }

    @Override
    public String answer(String text) {
        String requestId = UUID.randomUUID().toString();
        String idempotencyKey = UUID.randomUUID().toString();
        String traceparent = newTraceparent();

        HttpRequest request = HttpRequest.newBuilder(endpoint)
                .timeout(readTimeout)
                .header("X-Service-Name", SERVICE_NAME)
                .header("X-API-Key", apiKey)
                .header("X-Request-Id", requestId)
                .header("Idempotency-Key", idempotencyKey)
                .header("X-Protocol-Version", PROTOCOL_VERSION)
                .header("traceparent", traceparent)
                .header("Accept", "application/json")
                .header("Content-Type", "application/json")
                .POST(HttpRequest.BodyPublishers.ofString(
                        buildBody(requestId, text), StandardCharsets.UTF_8))
                .build();

        HttpResponse<String> response = send(request, requestId);
        int status = response.statusCode();
        if (status < 200 || status >= 300) {
            String safeCode = safeProblemCode(response.body());
            log.warn("gimbal AI downstream non-2xx requestId={} status={} code={}",
                    requestId, status, safeCode == null ? "<none>" : safeCode);
            throw new GimbalAiException(GimbalAiFailureKind.UNAVAILABLE,
                    "gimbal AI downstream returned a non-success status", status, safeCode);
        }
        return parseAnswer(response.body(), requestId, status);
    }

    private HttpResponse<String> send(HttpRequest request, String requestId) {
        try {
            return httpClient.send(request, HttpResponse.BodyHandlers.ofString(StandardCharsets.UTF_8));
        } catch (HttpTimeoutException timeout) {
            log.warn("gimbal AI downstream timeout requestId={}", requestId);
            throw new GimbalAiException(GimbalAiFailureKind.TIMEOUT,
                    "gimbal AI downstream timed out");
        } catch (InterruptedException interrupted) {
            Thread.currentThread().interrupt();
            throw new GimbalAiException(GimbalAiFailureKind.UNAVAILABLE,
                    "gimbal AI downstream call was interrupted");
        } catch (IOException transport) {
            log.warn("gimbal AI downstream transport failure requestId={} exception={}",
                    requestId, transport.getClass().getSimpleName());
            throw new GimbalAiException(GimbalAiFailureKind.UNAVAILABLE,
                    "gimbal AI downstream transport failure");
        }
    }

    private String parseAnswer(String body, String requestId, int status) {
        JsonNode root;
        try {
            root = objectMapper.readTree(body);
        } catch (Exception unparseable) {
            throw malformed(requestId, status, "response is not valid JSON");
        }
        if (root == null || !root.isObject()) {
            throw malformed(requestId, status, "response is not a JSON object");
        }
        JsonNode answer = root.get("answer");
        if (answer == null || !answer.isObject()) {
            throw malformed(requestId, status, "'answer' block missing or not an object");
        }
        JsonNode text = answer.get("text");
        if (text == null || !text.isTextual() || text.asText().isBlank()) {
            throw malformed(requestId, status, "'answer.text' missing or not a non-blank string");
        }
        return text.asText();
    }

    private GimbalAiException malformed(String requestId, int status, String detail) {
        log.warn("gimbal AI downstream malformed 2xx requestId={} status={} detail={}",
                requestId, status, detail);
        return new GimbalAiException(GimbalAiFailureKind.MALFORMED,
                "gimbal AI downstream returned a malformed success response", status, null);
    }

    private String buildBody(String requestId, String text) {
        try {
            ObjectNode root = objectMapper.createObjectNode();
            root.put("protocol_version", PROTOCOL_VERSION);
            root.put("request_id", requestId);
            root.put("use_case", USE_CASE);
            ObjectNode input = objectMapper.createObjectNode();
            input.put("text", text);
            root.set("input", input);
            return objectMapper.writeValueAsString(root);
        } catch (Exception encoding) {
            throw new GimbalAiException(GimbalAiFailureKind.UNAVAILABLE,
                    "gimbal AI downstream request could not be encoded");
        }
    }

    /** problem+json 的 code（仅用于日志；解析失败返回 null，绝不影响失败分类）。 */
    private String safeProblemCode(String body) {
        if (body == null || body.isBlank()) {
            return null;
        }
        try {
            JsonNode node = objectMapper.readTree(body).path("code");
            return node.isTextual() ? node.asText() : null;
        } catch (Exception ignored) {
            return null;
        }
    }

    private static String newTraceparent() {
        return "00-" + randomHex(16) + "-" + randomHex(8) + "-01";
    }

    private static String randomHex(int byteCount) {
        byte[] bytes = new byte[byteCount];
        RANDOM.nextBytes(bytes);
        StringBuilder builder = new StringBuilder(byteCount * 2);
        for (byte b : bytes) {
            builder.append(Character.forDigit((b >> 4) & 0xF, 16));
            builder.append(Character.forDigit(b & 0xF, 16));
        }
        return builder.toString();
    }
}

package cn.yuanxin.mvp.web.gimbalai;

import cn.yuanxin.mvp.web.config.AppProperties;
import cn.yuanxin.mvp.web.config.NonProductionCondition;
import cn.yuanxin.mvp.web.error.ApiException;
import cn.yuanxin.mvp.web.error.ErrorCode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.boot.context.properties.EnableConfigurationProperties;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.core.env.Environment;

import java.util.List;

/**
 * 云台 AI 客户端装配。优先级（与 B/C/D 既有 provider 约定一致）：
 * <pre>app.providers.mode=disabled （能力显式关闭） &gt; app.gimbal-ai 配置是否齐备</pre>
 *
 * <ul>
 *   <li>{@code mode=disabled} → 停机占位：调用即 503 DEPENDENCY_UNAVAILABLE
 *       （沿 {@code DisabledProvidersConfig} 占位接线语义）；</li>
 *   <li>配置齐备 → 真实 {@link HttpGimbalAiClient}；</li>
 *   <li>配置缺失且<b>非生产</b> → 停机占位（运行时 503，应用仍可启动）；</li>
 *   <li>配置缺失且<b>生产信号</b>（{@code app.env=production} 或 prod profile）→
 *       启动失败（fail-closed；消息只列键名）。</li>
 * </ul>
 *
 * <p>无替身回退：任何失败路径都不会产生合成答案。</p>
 */
@Configuration
@EnableConfigurationProperties(GimbalAiProperties.class)
public class GimbalAiProvidersConfig {

    @Bean
    public GimbalAiClient gimbalAiClient(GimbalAiProperties properties, Environment environment,
                                         ObjectMapper objectMapper) {
        return createClient(properties, environment, objectMapper);
    }

    /**
     * 可单测的工厂：按 mode/env/配置选择真实客户端或停机占位。
     * 缺失键仅在消息中列键名，绝不回显值。
     */
    static GimbalAiClient createClient(GimbalAiProperties properties, Environment environment,
                                       ObjectMapper objectMapper) {
        String mode = new AppProperties.Providers(
                environment.getProperty("app.providers.mode")).mode();
        if ("disabled".equals(mode)) {
            return unavailable("gimbal AI capability disabled by configuration");
        }
        List<String> missing = properties.missingRequiredKeys();
        if (missing.isEmpty()) {
            return new HttpGimbalAiClient(properties, objectMapper);
        }
        if (!NonProductionCondition.isNonProduction(environment)) {
            throw new IllegalStateException(
                    "production fail-closed: app.gimbal-ai missing required config keys " + missing
                            + " (values are never logged); configure base-url/api-key or set"
                            + " app.providers.mode=disabled");
        }
        return unavailable("gimbal AI capability is not configured");
    }

    private static GimbalAiClient unavailable(String reason) {
        return text -> {
            throw new ApiException(ErrorCode.DEPENDENCY_UNAVAILABLE, reason);
        };
    }
}

package cn.yuanxin.mvp.web.gimbalai;

import cn.yuanxin.mvp.web.auth.PrincipalContext;
import cn.yuanxin.mvp.web.auth.PrincipalType;
import cn.yuanxin.mvp.web.error.ApiException;
import cn.yuanxin.mvp.web.error.ErrorCode;
import cn.yuanxin.mvp.web.gimbalai.dto.GimbalAiAnswer;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;

/**
 * 云台 AI 文本透传业务入口（无状态、无副作用、无本地幂等存储）。
 *
 * <p>仅 {@link PrincipalType#GIMBAL} 可调用；APP 主体在<b>调用下游之前</b>拒绝
 * （403 CALLER_NOT_ALLOWED），绝无下游请求。</p>
 *
 * <p>失败映射（无 502 错误码，采用既有依赖类问题；如实记录该选择）：</p>
 * <ul>
 *   <li>{@code TIMEOUT} → 504 DEPENDENCY_TIMEOUT（可重试）；</li>
 *   <li>{@code MALFORMED} / {@code UNAVAILABLE}（含下游非 2xx）→ 503 DEPENDENCY_UNAVAILABLE。</li>
 * </ul>
 * <p><b>绝不</b>把失败映射为成功，也<b>绝不</b>回退替身/合成答案。</p>
 */
@Service
public class GimbalAiService {

    private static final Logger log = LoggerFactory.getLogger(GimbalAiService.class);

    /** 对客户端统一的最小依赖失败文案（不泄露下游诊断）。 */
    static final String DEPENDENCY_MESSAGE = "gimbal AI dependency failure; no answer available";

    private final GimbalAiClient client;

    public GimbalAiService(GimbalAiClient client) {
        this.client = client;
    }

    public GimbalAiAnswer ask(PrincipalContext principal, String text) {
        if (principal.principalType() != PrincipalType.GIMBAL) {
            throw new ApiException(ErrorCode.CALLER_NOT_ALLOWED,
                    "only a gimbal may use the AI text passthrough");
        }
        try {
            return new GimbalAiAnswer(client.answer(text));
        } catch (GimbalAiException failure) {
            ErrorCode code = switch (failure.kind()) {
                case TIMEOUT -> ErrorCode.DEPENDENCY_TIMEOUT;
                case MALFORMED, UNAVAILABLE -> ErrorCode.DEPENDENCY_UNAVAILABLE;
            };
            // 只记分类/状态/下游码；绝不记用户文本或密钥（requestId 由 MDC/日志框架携带）。
            log.warn("gimbal AI failure kind={} downstreamStatus={} downstreamCode={}",
                    failure.kind(), failure.httpStatus(),
                    failure.safeCode() == null ? "<none>" : failure.safeCode());
            throw new ApiException(code, DEPENDENCY_MESSAGE);
        }
    }
}

package cn.yuanxin.mvp.web.gimbalai;

import cn.yuanxin.mvp.web.auth.PrincipalContext;
import cn.yuanxin.mvp.web.gimbalai.dto.GimbalAiAnswer;
import cn.yuanxin.mvp.web.gimbalai.dto.GimbalAiMessageRequest;
import cn.yuanxin.mvp.web.web.EnvelopeSupport;
import cn.yuanxin.mvp.web.web.SuccessEnvelope;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.validation.Valid;
import org.springframework.http.ResponseEntity;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

/**
 * 云台 AI 文本透传 HTTP 端点（无状态、无上下文）。
 *
 * <p>POST /api/v1/gimbal-ai/messages：Bearer 认证（BearerAuthFilter）→ 仅云台主体
 * （APP → 403 CALLER_NOT_ALLOWED）→ 透传下游 AI 服务，返回
 * {@code SuccessEnvelope{ data:{answerText} }}。</p>
 *
 * <p>Controller 只做 HTTP 映射；授权与下游映射在 {@link GimbalAiService}。</p>
 */
@RestController
@Validated
@RequestMapping("/api/v1/gimbal-ai")
public class GimbalAiController {

    private final GimbalAiService service;
    private final EnvelopeSupport envelopes;

    public GimbalAiController(GimbalAiService service, EnvelopeSupport envelopes) {
        this.service = service;
        this.envelopes = envelopes;
    }

    @PostMapping("/messages")
    public ResponseEntity<SuccessEnvelope> messages(
            @Valid @RequestBody GimbalAiMessageRequest body,
            PrincipalContext principal, HttpServletRequest request) {
        GimbalAiAnswer data = service.ask(principal, body.text());
        return ResponseEntity.ok().body(envelopes.ok(request, data));
    }
}

