package cn.yuanxin.mvp.web.gimbalai;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;

import java.util.Set;

/**
 * AI 下游 {@code /internal/v1/ai/responses:stream} 的 SSE 解析器（严格 fail-closed）。
 *
 * <p>只接受四个事件：{@code response.accepted}（信息性）、{@code delta}（按序累加
 * {@code data.delta}）、{@code completed}（唯一成功终态；以其 {@code data.answer.text}
 * 为权威答案）、{@code failed}（终态失败，problem+json）。</p>
 *
 * <p><b>fail-closed 规则</b>：未知事件、事件后又有事件（含重复终态）、缺终态（EOF）、
 * 事件缺 data、data 非 JSON/非对象、{@code delta} 缺文本、{@code completed} 缺非空
 * {@code answer.text}、累计增量或事件数越界 → 一律抛 {@link GimbalAiException}
 * （{@code MALFORMED}）；{@code failed} → {@code UNAVAILABLE}。绝不返回部分/合成答案。</p>
 *
 * <p>SSE 语法按规范处理：以空行分隔事件块，忽略注释行（以 {@code :} 开头）与
 * {@code id}/{@code retry} 字段，{@code data:} 后可跨多行，行尾兼容 CR/LF/CRLF。
 * <b>不</b>发送或解析 Last-Event-ID，绝不断点续传。</p>
 */
final class GimbalAiSseParser {

    private static final ObjectMapper MAPPER = new ObjectMapper();

    private static final Set<String> EVENTS =
            Set.of("response.accepted", "delta", "completed", "failed");

    /** 单次流事件的硬上限（防无界事件流）。 */
    static final int MAX_EVENTS = 10_000;
    /** 累计 delta 字符数硬上限（completed.answer.text 为权威答案，此处仅防无界累积）。 */
    static final int MAX_ACCUMULATED_CHARS = 200_000;

    private GimbalAiSseParser() {
    }

    static String parse(String body) {
        if (body == null || body.isBlank()) {
            throw malformed("stream body is empty");
        }
        State state = new State();
        StringBuilder deltas = new StringBuilder();
        String eventName = null;
        StringBuilder data = new StringBuilder();
        boolean hasData = false;
        int eventCount = 0;

        for (String line : body.split("\r\n|\n|\r", -1)) {
            if (line.isEmpty()) {
                if (eventName != null || hasData) {
                    eventCount = dispatch(eventName, hasData ? data.toString() : null, state, deltas,
                            eventCount);
                }
                eventName = null;
                data.setLength(0);
                hasData = false;
                continue;
            }
            if (line.startsWith(":")) {
                continue; // SSE 注释
            }
            int colon = line.indexOf(':');
            String field = colon < 0 ? line : line.substring(0, colon);
            String value = colon < 0 ? "" : line.substring(colon + 1);
            if (value.startsWith(" ")) {
                value = value.substring(1);
            }
            switch (field) {
                case "event" -> eventName = value;
                case "data" -> {
                    if (hasData) {
                        data.append('\n');
                    }
                    data.append(value);
                    hasData = true;
                }
                default -> {
                    // id/retry/未知字段：忽略（绝不据此续传；无 Last-Event-ID）。
                }
            }
        }
        // EOF：处理最后一个未以空行结束的块。
        if (eventName != null || hasData) {
            dispatch(eventName, hasData ? data.toString() : null, state, deltas, eventCount);
        }

        if (!state.terminal) {
            throw malformed("stream ended without a completed terminal event");
        }
        return state.answer;
    }

    private static int dispatch(String event, String data, State state, StringBuilder deltas,
                                int eventCount) {
        int count = eventCount + 1;
        if (count > MAX_EVENTS) {
            throw malformed("stream exceeded the maximum event count");
        }
        if (event == null) {
            throw malformed("stream data without an event name");
        }
        if (!EVENTS.contains(event)) {
            throw malformed("unknown stream event: " + event);
        }
        if (state.terminal) {
            throw malformed("stream event after the terminal event: " + event);
        }
        if (data == null) {
            throw malformed("stream event missing data: " + event);
        }
        JsonNode root;
        try {
            root = MAPPER.readTree(data);
        } catch (Exception unparseable) {
            throw malformed("stream event data is not valid JSON");
        }
        if (root == null || !root.isObject()) {
            throw malformed("stream event data is not a JSON object");
        }
        switch (event) {
            case "response.accepted" -> {
                // 信息性事件：无需字段，不改变状态。
            }
            case "delta" -> {
                JsonNode delta = root.get("delta");
                if (delta == null || !delta.isTextual()) {
                    throw malformed("delta event missing a textual 'delta'");
                }
                deltas.append(delta.asText());
                if (deltas.length() > MAX_ACCUMULATED_CHARS) {
                    throw malformed("accumulated delta exceeded the maximum length");
                }
            }
            case "completed" -> {
                JsonNode text = root.path("answer").path("text");
                if (!text.isTextual() || text.asText().isBlank()) {
                    throw malformed("completed event missing a non-blank answer.text");
                }
                state.answer = text.asText();
                state.terminal = true;
            }
            case "failed" -> {
                String code = root.path("code").isTextual() ? root.path("code").asText() : null;
                throw new GimbalAiException(GimbalAiFailureKind.UNAVAILABLE,
                        "gimbal AI downstream reported a failed stream", null, code);
            }
            default -> throw malformed("unknown stream event: " + event);
        }
        return count;
    }

    private static GimbalAiException malformed(String detail) {
        return new GimbalAiException(GimbalAiFailureKind.MALFORMED,
                "gimbal AI downstream returned a malformed success stream", null, null);
    }

    private static final class State {
        private boolean terminal;
        private String answer;
    }
}

