package cn.yuanxin.mvp.web.gimbalai;

/**
 * 下游 SSE 事件（已由 {@link GimbalAiSseParser} 校验并归一化）。
 *
 * <p>只允许四个类型：{@code ACCEPTED}（信息性）、{@code DELTA}（{@link #delta()}）、
 * {@code COMPLETED}（{@link #answerText()} 权威）、{@code FAILED}（{@link #failedCode()}）。</p>
 */
record GimbalAiEvent(Type type, String delta, String answerText, String failedCode) {

    enum Type {
        ACCEPTED,
        DELTA,
        COMPLETED,
        FAILED
    }

    static GimbalAiEvent accepted() {
        return new GimbalAiEvent(Type.ACCEPTED, null, null, null);
    }

    static GimbalAiEvent delta(String delta) {
        return new GimbalAiEvent(Type.DELTA, delta, null, null);
    }

    static GimbalAiEvent completed(String answerText) {
        return new GimbalAiEvent(Type.COMPLETED, null, answerText, null);
    }

    static GimbalAiEvent failed(String failedCode) {
        return new GimbalAiEvent(Type.FAILED, null, null, failedCode);
    }
}

package cn.yuanxin.mvp.web.gimbalai;

/**
 * SSE 行源：每次返回一行（不含行尾），流结束返回 {@code null}；读取超时/传输失败由
 * 实现抛 {@link GimbalAiException}。{@link #close()} 必须能解除阻塞的读取并取消下游连接。
 */
interface GimbalAiLineSource extends AutoCloseable {

    /** @return 下一行（不含行尾）；{@code null} 表示流正常结束 */
    String readLine();

    @Override
    void close();
}

package cn.yuanxin.mvp.web.gimbalai;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Set;

/**
 * 下游 {@code /internal/v1/ai/responses:stream} 的<b>增量</b> SSE 解析器（严格 fail-closed）。
 *
 * <p>只接受四个事件：{@code response.accepted}（信息性）、{@code delta}（按序累加
 * {@code data.delta}）、{@code completed}（成功终态；{@code data.answer.text} 权威）、
 * {@code failed}（终态失败，problem+json 的 {@code code} 仅作诊断）。</p>
 *
 * <p><b>fail-closed</b>：未知事件、事件后又有事件（含重复终态）、缺终态（EOF）、
 * 事件缺 data、data 非 JSON/非对象、{@code delta} 缺文本、{@code completed} 缺非空
 * {@code answer.text}、事件数/累计增量越界 → 抛 {@link GimbalAiException}（{@code MALFORMED}）。
 * 读取超时/传输失败由行源抛 {@code TIMEOUT}/{@code UNAVAILABLE}。绝不返回部分/合成答案。</p>
 *
 * <p>SSE 语法：空行分隔事件块；忽略注释行（{@code :} 开头）与 {@code id}/{@code retry}
 * 字段；{@code data:} 可跨多行；行尾由行源处理。<b>不</b>发送或解析 Last-Event-ID。</p>
 *
 * <p>终止策略：遇到终态事件后，仍继续读到流结束以检出"终态后事件/重复终态"；此类违规
 * 一律 malformed。终态事件在流结束（EOF）后才可被消费，从而保证恰一个终态。</p>
 */
final class GimbalAiSseParser implements AutoCloseable {

    private static final ObjectMapper MAPPER = new ObjectMapper();

    private static final Set<String> EVENTS =
            Set.of("response.accepted", "delta", "completed", "failed");

    /** 单次流事件的硬上限（防无界事件流）。 */
    static final int MAX_EVENTS = 10_000;
    /** 累计 delta 字符数硬上限（completed.answer.text 为权威答案，此处仅防无界累积）。 */
    static final int MAX_ACCUMULATED_CHARS = 200_000;

    private final GimbalAiLineSource source;
    private final Deque<GimbalAiEvent> ready = new ArrayDeque<>();

    private boolean done;
    private boolean terminalSeen;
    private GimbalAiEvent pendingTerminal;

    private String eventName;
    private final StringBuilder data = new StringBuilder();
    private boolean hasData;
    private int eventCount;
    private int accumulatedChars;

    GimbalAiSseParser(GimbalAiLineSource source) {
        this.source = source;
    }

    /**
     * 下一个已校验事件；流在终态后正常结束返回 {@code null}。
     *
     * @throws GimbalAiException 协议违规（MALFORMED）或读取超时/传输失败（TIMEOUT/UNAVAILABLE）
     */
    GimbalAiEvent next() {
        if (!ready.isEmpty()) {
            return ready.poll();
        }
        if (done) {
            return null;
        }
        while (ready.isEmpty() && !done) {
            String line = source.readLine();
            if (line == null) {
                flushBlock();
                if (!terminalSeen) {
                    throw malformed("stream ended without a terminal event");
                }
                if (pendingTerminal != null) {
                    ready.add(pendingTerminal);
                    pendingTerminal = null;
                }
                done = true;
                break;
            }
            if (line.isEmpty()) {
                flushBlock();
                continue;
            }
            if (line.startsWith(":")) {
                continue;
            }
            int colon = line.indexOf(':');
            String field = colon < 0 ? line : line.substring(0, colon);
            String value = colon < 0 ? "" : line.substring(colon + 1);
            if (value.startsWith(" ")) {
                value = value.substring(1);
            }
            switch (field) {
                case "event" -> eventName = value;
                case "data" -> {
                    if (hasData) {
                        data.append('\n');
                    }
                    data.append(value);
                    hasData = true;
                }
                default -> {
                    // id/retry/未知字段：忽略；绝不断点续传。
                }
            }
        }
        return ready.poll();
    }

    private void flushBlock() {
        String name = eventName;
        boolean hadData = hasData;
        String payload = hasData ? data.toString() : null;
        eventName = null;
        data.setLength(0);
        hasData = false;
        if (name == null && !hadData) {
            return;
        }
        eventCount++;
        if (eventCount > MAX_EVENTS) {
            throw malformed("stream exceeded the maximum event count");
        }
        if (name == null) {
            throw malformed("stream data without an event name");
        }
        if (!EVENTS.contains(name)) {
            throw malformed("unknown stream event: " + name);
        }
        if (terminalSeen) {
            throw malformed("stream event after the terminal event: " + name);
        }
        if (payload == null) {
            throw malformed("stream event missing data: " + name);
        }
        JsonNode root;
        try {
            root = MAPPER.readTree(payload);
        } catch (Exception unparseable) {
            throw malformed("stream event data is not valid JSON");
        }
        if (root == null || !root.isObject()) {
            throw malformed("stream event data is not a JSON object");
        }
        switch (name) {
            case "response.accepted" -> ready.add(GimbalAiEvent.accepted());
            case "delta" -> {
                JsonNode delta = root.get("delta");
                if (delta == null || !delta.isTextual()) {
                    throw malformed("delta event missing a textual 'delta'");
                }
                accumulatedChars += delta.asText().length();
                if (accumulatedChars > MAX_ACCUMULATED_CHARS) {
                    throw malformed("accumulated delta exceeded the maximum length");
                }
                ready.add(GimbalAiEvent.delta(delta.asText()));
            }
            case "completed" -> {
                JsonNode text = root.path("answer").path("text");
                if (!text.isTextual() || text.asText().isBlank()) {
                    throw malformed("completed event missing a non-blank answer.text");
                }
                terminalSeen = true;
                pendingTerminal = GimbalAiEvent.completed(text.asText());
            }
            case "failed" -> {
                String code = root.path("code").isTextual() ? root.path("code").asText() : null;
                terminalSeen = true;
                pendingTerminal = GimbalAiEvent.failed(code);
            }
            default -> throw malformed("unknown stream event: " + name);
        }
    }

    @Override
    public void close() {
        source.close();
    }

    private static GimbalAiException malformed(String detail) {
        return new GimbalAiException(GimbalAiFailureKind.MALFORMED,
                "gimbal AI downstream returned a malformed success stream: " + detail, null, null);
    }
}

