package cn.yuanxin.mvp.web.gimbalai;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ObjectNode;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.net.http.HttpTimeoutException;
import java.nio.charset.StandardCharsets;
import java.security.SecureRandom;
import java.time.Duration;
import java.util.UUID;
import java.util.concurrent.BlockingQueue;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.LinkedBlockingQueue;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.TimeoutException;

/**
 * 云台 AI 文本透传下游客户端（JDK {@link HttpClient}；<b>SSE 流式</b>；无状态、无重试回退）。
 *
 * <p>固定契约（对 {@code POST {base}/internal/v1/ai/responses:stream}）：</p>
 * <ul>
 *   <li>Header：{@code X-Service-Name=medical-platform}、{@code X-API-Key}（配置）、
 *       {@code X-Request-Id}（每次调用服务端新生成）、{@code Idempotency-Key}
 *       （<b>每次调用全新</b>，故客户端重试会产生<b>新问题</b>；本增量无本地幂等存储）、
 *       {@code X-Protocol-Version=1.0}、{@code traceparent}（W3C）、
 *       {@code Accept: text/event-stream}、{@code Content-Type: application/json}；
 *       <b>不发送</b> Last-Event-ID（绝不续传）；</li>
 *   <li>Body：{@code {"protocol_version":"1.0","request_id":"<X-Request-Id>",
 *       "use_case":"APP_AGENT_CONVERSATION","input":{"text":"<用户文本>"}}}；不含
 *       {@code continuation_state}；</li>
 *   <li>预流：非 2xx → {@code UNAVAILABLE}；连接失败 → {@code UNAVAILABLE}；预流超时 → {@code TIMEOUT}；
 *       流内：由 {@link GimbalAiSseParser} 增量严格校验，读取超时 → {@code TIMEOUT}，传输/EOF 违规 →
 *       {@code MALFORMED}/{@code UNAVAILABLE}。</li>
 * </ul>
 *
 * <p><b>绝不</b>回退到一次性 {@code /internal/v1/ai/responses}；<b>绝不</b>合成答案。</p>
 *
 * <p><b>日志</b>：只记下游 requestId / HTTP 状态 / 下游错误码 / 失败分类；绝不记 API Key、
 * 用户文本、SSE 原文。</p>
 */
public class HttpGimbalAiClient implements GimbalAiClient {

    private static final Logger log = LoggerFactory.getLogger(HttpGimbalAiClient.class);

    static final String SERVICE_NAME = "medical-platform";
    static final String USE_CASE = "APP_AGENT_CONVERSATION";
    static final String PROTOCOL_VERSION = "1.0";
    static final String RESPONSES_STREAM_PATH = "/internal/v1/ai/responses:stream";

    private static final SecureRandom RANDOM = new SecureRandom();

    private final HttpClient httpClient;
    private final ObjectMapper objectMapper;
    private final URI endpoint;
    private final String apiKey;
    private final long readTimeoutMillis;

    public HttpGimbalAiClient(GimbalAiProperties properties, ObjectMapper objectMapper) {
        this(properties, objectMapper, HttpClient.newBuilder()
                .connectTimeout(Duration.ofMillis(properties.connectTimeoutMillis()))
                .build());
    }

    /** 测试用构造器：注入自定义 HttpClient（如指向本地 stub 的连接池）。 */
    HttpGimbalAiClient(GimbalAiProperties properties, ObjectMapper objectMapper,
                       HttpClient httpClient) {
        this.objectMapper = objectMapper;
        this.httpClient = httpClient;
        this.endpoint = URI.create(properties.normalizedBaseUrl() + RESPONSES_STREAM_PATH);
        this.apiKey = properties.apiKey();
        this.readTimeoutMillis = properties.readTimeoutMillis();
    }

    @Override
    public GimbalAiStream openStream(String text) {
        String requestId = UUID.randomUUID().toString();
        String idempotencyKey = UUID.randomUUID().toString();
        String traceparent = newTraceparent();

        HttpRequest request = HttpRequest.newBuilder(endpoint)
                .header("X-Service-Name", SERVICE_NAME)
                .header("X-API-Key", apiKey)
                .header("X-Request-Id", requestId)
                .header("Idempotency-Key", idempotencyKey)
                .header("X-Protocol-Version", PROTOCOL_VERSION)
                .header("traceparent", traceparent)
                .header("Accept", "text/event-stream")
                .header("Content-Type", "application/json")
                .POST(HttpRequest.BodyPublishers.ofString(
                        buildBody(requestId, text), StandardCharsets.UTF_8))
                .build();

        HttpResponse<InputStream> response = sendForHeaders(request, requestId);
        int status = response.statusCode();
        if (status < 200 || status >= 300) {
            String safeCode = safeProblemCode(readProblemBody(response.body()));
            log.warn("gimbal AI downstream non-2xx requestId={} status={} code={}",
                    requestId, status, safeCode == null ? "<none>" : safeCode);
            closeQuietly(response.body());
            throw new GimbalAiException(GimbalAiFailureKind.UNAVAILABLE,
                    "gimbal AI downstream returned a non-success status", status, safeCode);
        }
        GimbalAiSseParser parser = new GimbalAiSseParser(
                new TimeoutLineSource(response.body(), readTimeoutMillis));
        log.info("gimbal AI downstream stream opened requestId={} status={}", requestId, status);
        return new GimbalAiStream() {
            @Override
            public GimbalAiEvent next() {
                return parser.next();
            }

            @Override
            public void close() {
                parser.close();
            }
        };
    }

    /** 预流：以 read-timeout 约束"响应头到达"；预流超时 → TIMEOUT，连接失败 → UNAVAILABLE。 */
    private HttpResponse<InputStream> sendForHeaders(HttpRequest request, String requestId) {
        try {
            return httpClient.sendAsync(request, HttpResponse.BodyHandlers.ofInputStream())
                    .get(readTimeoutMillis, TimeUnit.MILLISECONDS);
        } catch (TimeoutException timeout) {
            log.warn("gimbal AI downstream pre-stream timeout requestId={}", requestId);
            throw new GimbalAiException(GimbalAiFailureKind.TIMEOUT,
                    "gimbal AI downstream timed out before streaming");
        } catch (InterruptedException interrupted) {
            Thread.currentThread().interrupt();
            throw new GimbalAiException(GimbalAiFailureKind.UNAVAILABLE,
                    "gimbal AI downstream call was interrupted");
        } catch (ExecutionException failure) {
            Throwable cause = failure.getCause();
            if (cause instanceof HttpTimeoutException) {
                throw new GimbalAiException(GimbalAiFailureKind.TIMEOUT,
                        "gimbal AI downstream timed out before streaming");
            }
            log.warn("gimbal AI downstream transport failure requestId={} exception={}",
                    requestId, cause == null ? "unknown" : cause.getClass().getSimpleName());
            throw new GimbalAiException(GimbalAiFailureKind.UNAVAILABLE,
                    "gimbal AI downstream transport failure");
        }
    }

    private String readProblemBody(InputStream body) {
        if (body == null) {
            return null;
        }
        try {
            return new String(body.readAllBytes(), StandardCharsets.UTF_8);
        } catch (IOException unreadable) {
            return null;
        }
    }

    private static void closeQuietly(InputStream body) {
        if (body == null) {
            return;
        }
        try {
            body.close();
        } catch (IOException ignored) {
            // best effort
        }
    }

    private String buildBody(String requestId, String text) {
        try {
            ObjectNode root = objectMapper.createObjectNode();
            root.put("protocol_version", PROTOCOL_VERSION);
            root.put("request_id", requestId);
            root.put("use_case", USE_CASE);
            ObjectNode input = objectMapper.createObjectNode();
            input.put("text", text);
            root.set("input", input);
            return objectMapper.writeValueAsString(root);
        } catch (Exception encoding) {
            throw new GimbalAiException(GimbalAiFailureKind.UNAVAILABLE,
                    "gimbal AI downstream request could not be encoded");
        }
    }

    /** problem+json 的 code（仅用于日志；解析失败返回 null，绝不影响失败分类）。 */
    private String safeProblemCode(String body) {
        if (body == null || body.isBlank()) {
            return null;
        }
        try {
            JsonNode node = objectMapper.readTree(body).path("code");
            return node.isTextual() ? node.asText() : null;
        } catch (Exception ignored) {
            return null;
        }
    }

    private static String newTraceparent() {
        return "00-" + randomHex(16) + "-" + randomHex(8) + "-01";
    }

    private static String randomHex(int byteCount) {
        byte[] bytes = new byte[byteCount];
        RANDOM.nextBytes(bytes);
        StringBuilder builder = new StringBuilder(byteCount * 2);
        for (byte b : bytes) {
            builder.append(Character.forDigit((b >> 4) & 0xF, 16));
            builder.append(Character.forDigit(b & 0xF, 16));
        }
        return builder.toString();
    }

    /**
     * 带单次读取超时的 SSE 行源：工作线程阻塞读行入队；消费侧按 read-timeout 轮询。
     * 超时即关闭底层 InputStream（取消下游交换）并抛 {@code TIMEOUT}；传输失败抛
     * {@code UNAVAILABLE}。{@link #close()} 解除阻塞并取消连接（客户端断开时调用）。
     */
    private static final class TimeoutLineSource implements GimbalAiLineSource {

        private static final Object EOF = new Object();

        private final BufferedReader reader;
        private final long timeoutMillis;
        private final BlockingQueue<Object> queue = new LinkedBlockingQueue<>();
        private final Thread worker;

        TimeoutLineSource(InputStream body, long timeoutMillis) {
            this.reader = new BufferedReader(new InputStreamReader(body, StandardCharsets.UTF_8));
            this.timeoutMillis = timeoutMillis;
            this.worker = new Thread(this::pump, "gimbal-ai-sse-reader");
            this.worker.setDaemon(true);
            this.worker.start();
        }

        private void pump() {
            try {
                String line;
                while ((line = reader.readLine()) != null) {
                    queue.add(line);
                }
                queue.add(EOF);
            } catch (IOException io) {
                queue.add(io);
            }
        }

        @Override
        public String readLine() {
            Object item;
            try {
                item = queue.poll(timeoutMillis, TimeUnit.MILLISECONDS);
            } catch (InterruptedException interrupted) {
                Thread.currentThread().interrupt();
                close();
                throw new GimbalAiException(GimbalAiFailureKind.UNAVAILABLE,
                        "gimbal AI downstream read interrupted");
            }
            if (item == null) {
                close();
                throw new GimbalAiException(GimbalAiFailureKind.TIMEOUT,
                        "gimbal AI downstream stream read timed out");
            }
            if (item == EOF) {
                return null;
            }
            if (item instanceof IOException) {
                throw new GimbalAiException(GimbalAiFailureKind.UNAVAILABLE,
                        "gimbal AI downstream stream transport failure");
            }
            return (String) item;
        }

        @Override
        public void close() {
            try {
                reader.close();
            } catch (IOException ignored) {
                // best effort
            }
            worker.interrupt();
        }
    }
}

package cn.yuanxin.mvp.web.gimbalai;

import cn.yuanxin.mvp.web.auth.PrincipalContext;
import cn.yuanxin.mvp.web.auth.PrincipalType;
import cn.yuanxin.mvp.web.error.ApiException;
import cn.yuanxin.mvp.web.error.ErrorCode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;

import java.io.IOException;
import java.io.OutputStream;
import java.nio.charset.StandardCharsets;
import java.util.LinkedHashMap;
import java.util.Map;

/**
 * 云台 AI 文本透传业务入口（无状态、无副作用、无本地幂等存储）。
 *
 * <p>仅 {@link PrincipalType#GIMBAL} 可调用；APP 主体在<b>打开下游之前</b>拒绝
 * （403 CALLER_NOT_ALLOWED），绝无下游请求。</p>
 *
 * <p><b>预流失败</b>（授权、下游连接/预流非 2xx/预流超时）以 {@link ApiException}
 * 上抛 → 统一 JSON problem 映射；<b>流内失败</b>（畸形 SSE、缺终态、EOF、读超时）
 * 转成<b>恰好一个</b>外部 {@code failed} 终态事件（安全 code/message）。</p>
 *
 * <p><b>逐事件解析-校验-重编码</b>（白名单），绝不做字节透传：外部只发
 * {@code response.accepted}/{@code delta}/{@code completed}/{@code failed}；每事件后
 * {@code flush()}，绝不缓冲整段答案。</p>
 */
@Service
public class GimbalAiService {

    private static final Logger log = LoggerFactory.getLogger(GimbalAiService.class);

    /** 对客户端统一的最小依赖失败文案（不泄露下游诊断）。 */
    static final String DEPENDENCY_MESSAGE = "gimbal AI dependency failure; no answer available";

    private final GimbalAiClient client;
    private final ObjectMapper objectMapper;

    public GimbalAiService(GimbalAiClient client, ObjectMapper objectMapper) {
        this.client = client;
        this.objectMapper = objectMapper;
    }

    /**
     * 鉴权 + 打开下游流。预流失败会抛异常（由 MVC advice 映射为 JSON problem）。
     */
    public GimbalAiStream openStream(PrincipalContext principal, String text) {
        if (principal.principalType() != PrincipalType.GIMBAL) {
            throw new ApiException(ErrorCode.CALLER_NOT_ALLOWED,
                    "only a gimbal may use the AI text passthrough");
        }
        return client.openStream(text);
    }

    /**
     * 消费下游事件并逐事件重编码为外部 SSE 写到 {@code out}。
     *
     * <p>恰一个终态：{@code completed} 或 {@code failed}。客户端断开（写 IOException）
     * 时不写 failed，直接上抛，由调用方在 finally 关闭下游流（取消下游）。</p>
     */
    public void pump(GimbalAiStream stream, OutputStream out) throws IOException {
        try {
            GimbalAiEvent event;
            while ((event = stream.next()) != null) {
                switch (event.type()) {
                    case ACCEPTED -> writeEvent(out, "response.accepted", json(Map.of()));
                    case DELTA -> writeEvent(out, "delta", json(Map.of("delta", event.delta())));
                    case COMPLETED -> {
                        writeEvent(out, "completed", json(Map.of("answerText", event.answerText())));
                        return;
                    }
                    case FAILED -> {
                        writeFailed(out, codeForFailedEvent(event.failedCode()));
                        return;
                    }
                }
            }
            // 解析器保证终态；防御性兜底：仍按失败终态处理（绝不静默成功）。
            writeFailed(out, ErrorCode.DEPENDENCY_UNAVAILABLE);
        } catch (GimbalAiException failure) {
            ErrorCode code = failure.kind() == GimbalAiFailureKind.TIMEOUT
                    ? ErrorCode.DEPENDENCY_TIMEOUT
                    : ErrorCode.DEPENDENCY_UNAVAILABLE;
            // 只记分类/状态/下游码；绝不记用户文本、密钥或 SSE 原文（requestId 由 MDC 携带）。
            log.warn("gimbal AI stream failure kind={} downstreamStatus={} downstreamCode={}",
                    failure.kind(), failure.httpStatus(),
                    failure.safeCode() == null ? "<none>" : failure.safeCode());
            writeFailed(out, code);
        }
    }

    private static ErrorCode codeForFailedEvent(String downstreamCode) {
        if (downstreamCode != null && downstreamCode.toUpperCase().contains("TIMEOUT")) {
            return ErrorCode.DEPENDENCY_TIMEOUT;
        }
        return ErrorCode.DEPENDENCY_UNAVAILABLE;
    }

    private void writeFailed(OutputStream out, ErrorCode code) throws IOException {
        Map<String, Object> data = new LinkedHashMap<>();
        data.put("code", code.name());
        data.put("message", DEPENDENCY_MESSAGE);
        writeEvent(out, "failed", json(data));
    }

    private void writeEvent(OutputStream out, String event, String jsonData) throws IOException {
        out.write(("event: " + event + "\ndata: " + jsonData + "\n\n")
                .getBytes(StandardCharsets.UTF_8));
        out.flush();
    }

    private String json(Object value) {
        try {
            return objectMapper.writeValueAsString(value);
        } catch (Exception encoding) {
            throw new IllegalStateException("failed to encode SSE event payload");
        }
    }
}

package cn.yuanxin.mvp.web.gimbalai;

import cn.yuanxin.mvp.web.auth.PrincipalContext;
import cn.yuanxin.mvp.web.gimbalai.dto.GimbalAiMessageRequest;
import jakarta.validation.Valid;
import org.springframework.http.CacheControl;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.servlet.mvc.method.annotation.StreamingResponseBody;

/**
 * 云台 AI 文本透传 HTTP 端点（无状态、无上下文；响应为 SSE）。
 *
 * <p>POST /api/v1/gimbal-ai/messages：Bearer 认证（BearerAuthFilter）→ 仅云台主体
 * （APP → 403 CALLER_NOT_ALLOWED）。<b>预流失败</b>（授权、校验、下游连接/预流非 2xx/
 * 预流超时）在返回前抛异常 → 统一 JSON problem；<b>成功预流</b>后以
 * {@code Content-Type: text/event-stream} 逐事件推送
 * {@code response.accepted}/{@code delta}/{@code completed}/{@code failed}（每事件 flush，
 * 绝不缓冲整段答案），流内失败转成恰好一个 {@code failed} 终态。</p>
 */
@RestController
@Validated
@RequestMapping("/api/v1/gimbal-ai")
public class GimbalAiController {

    private final GimbalAiService service;

    public GimbalAiController(GimbalAiService service) {
        this.service = service;
    }

    @PostMapping("/messages")
    public ResponseEntity<StreamingResponseBody> messages(
            @Valid @RequestBody GimbalAiMessageRequest body,
            PrincipalContext principal) {
        // 预流失败（含 APP 403、下游预流失败）在此抛出 → advice 返回 JSON problem。
        GimbalAiStream downstream = service.openStream(principal, body.text());
        StreamingResponseBody stream = output -> {
            try {
                service.pump(downstream, output);
            } finally {
                // 正常完成或客户端断开：始终取消/关闭下游连接。
                downstream.close();
            }
        };
        return ResponseEntity.ok()
                .contentType(MediaType.TEXT_EVENT_STREAM)
                .cacheControl(CacheControl.noStore())
                .body(stream);
    }
}

package cn.yuanxin.mvp.web.docs.catalog;

import cn.yuanxin.mvp.web.config.NonProductionCondition;
